steps.script:
var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
var n := 0
for c in layer.get_children():
	if c.has_meta("unit_id") and str(c.get_meta("unit_id")) == "U_WITCHSEEKERS_C" and bool(c.get("katah_readied_marker")):
		n += 1
return n

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_WITCHSEEKERS_C", {})
var staged: Array = md.get("staged_moves", [])
print("[cus11e calistus] staged moves: ", staged.size(), " ", md.get("model_distances", {}))
return staged.size()

var u = GameState.get_unit("U_WITCHSEEKERS_C")
var ok := true
for m in u.models:
	if float(m.position.y) > 1600.0 - 12.6:
		ok = false
print("[cus11e calistus] final positions: ", u.models.map(func(m): return m.position))
return ok
